<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';require_login();require_once __DIR__ . '/../includes/db.php';$userId=current_user_id();
$stmt=$conn->prepare("SELECT r.*,s.title,reviewer.F_name,reviewer.L_name FROM `REVIEW` r JOIN `SESSION_BOOKING` sb ON sb.booking_id=r.booking_id JOIN `SKILL` s ON s.skill_id=sb.skill_id JOIN `USER` reviewer ON reviewer.user_id=r.user_id WHERE s.user_id=? ORDER BY r.review_date DESC");$stmt->bind_param('i',$userId);$stmt->execute();$received=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$stmt=$conn->prepare("SELECT r.*,s.title,owner.F_name,owner.L_name FROM `REVIEW` r JOIN `SESSION_BOOKING` sb ON sb.booking_id=r.booking_id JOIN `SKILL` s ON s.skill_id=sb.skill_id JOIN `USER` owner ON owner.user_id=s.user_id WHERE r.user_id=? ORDER BY r.review_date DESC");$stmt->bind_param('i',$userId);$stmt->execute();$written=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$pageTitle='Reviews';require __DIR__.'/../includes/header.php';
?>
<section class="py-4 py-lg-5"><div class="container"><div class="mb-4"><div class="eyebrow text-primary mb-1">Community feedback</div><h1 class="section-title h2">Reviews</h1></div><div class="row g-4"><div class="col-lg-6"><div class="surface-card p-4 h-100"><h2 class="h5 mb-3">Received</h2><?php if(!$received):?><p class="text-secondary">No reviews received yet.</p><?php endif;?><?php foreach($received as $review):?><article class="border-bottom py-3"><div class="d-flex justify-content-between"><strong><?=e($review['title'])?></strong><span class="rating-stars"><?=str_repeat('★',(int)$review['rating'])?></span></div><p class="mb-1 text-secondary"><?=e($review['comment']?:'No comment.')?></p><small class="text-secondary">By <?=e(trim($review['F_name'].' '.$review['L_name']))?> on <?=e(date('M j, Y',strtotime($review['review_date'])))?></small></article><?php endforeach;?></div></div><div class="col-lg-6"><div class="surface-card p-4 h-100"><h2 class="h5 mb-3">Written by me</h2><?php if(!$written):?><p class="text-secondary">You have not written a review yet.</p><?php endif;?><?php foreach($written as $review):?><article class="border-bottom py-3"><div class="d-flex justify-content-between"><strong><?=e($review['title'])?></strong><span class="rating-stars"><?=str_repeat('★',(int)$review['rating'])?></span></div><p class="mb-1 text-secondary"><?=e($review['comment']?:'No comment.')?></p><small class="text-secondary">For <?=e(trim($review['F_name'].' '.$review['L_name']))?></small></article><?php endforeach;?></div></div></div></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
